from typing import Dict

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    sections: Dict[str, Dict[str, str]] = {}
    default_section: Dict[str, str] = {}
    mode: str | None = None
    current_dict: Dict[str, str] | None = None
    current_key: str | None = None
    value_parts: list[str] = []
    lines = text.splitlines()
    for line in lines:
        raw_line = line.rstrip('\n')
        if not raw_line.strip():
            continue
        if raw_line.lstrip().startswith((';', '#')):
            continue
        # strip inline comment (whitespace followed by ; or #)
        in_quotes = False
        i = 0
        while i < len(raw_line):
            ch = raw_line[i]
            if ch == '"' and (i == 0 or raw_line[i-1] != '\\'):
                in_quotes = not in_quotes
            if i > 0 and raw_line[i] in ';#' and raw_line[i-1].isspace() and not in_quotes:
                raw_line = raw_line[:i].rstrip()
                break
            i += 1
        if current_key is not None and raw_line and raw_line[0].isspace():
            cont = raw_line.strip()
            value_parts.append('\n' + cont)
            continue
        if raw_line.startswith('[') and raw_line.endswith(']'):
            if current_key is not None:
                current_dict[current_key] = ''.join(value_parts) if value_parts else ''
                current_key = None
                value_parts = []
            sec_name = raw_line[1:-1].strip()
            if sec_name == 'DEFAULT':
                mode = 'DEFAULT'
                current_dict = default_section
            else:
                mode = sec_name
                if sec_name not in sections:
                    sections[sec_name] = {}
                current_dict = sections[sec_name]
            continue
        if mode is None:
            raise ValueError('key before any section')
        eq_idx = raw_line.find('=')
        colon_idx = raw_line.find(':')
        split_idx = -1
        if eq_idx != -1 and colon_idx != -1:
            split_idx = min(eq_idx, colon_idx)
        elif eq_idx != -1:
            split_idx = eq_idx
        elif colon_idx != -1:
            split_idx = colon_idx
        else:
            raise ValueError(f'malformed line: {raw_line!r}')
        key = raw_line[:split_idx].strip().lower()
        val_raw = raw_line[split_idx+1:].strip()
        if val_raw.startswith('"') and val_raw.endswith('"'):
            val = val_raw[1:-1]
        else:
            val = val_raw
        if current_key is not None:
            current_dict[current_key] = ''.join(value_parts) if value_parts else ''
        current_key = key
        value_parts = [val]
        continue
    if current_key is not None:
        if mode is None:
            raise ValueError('key before any section')
        current_dict[current_key] = ''.join(value_parts) if value_parts else ''
        current_key = None
        value_parts = []

    # ---------- interpolation resolution ----------
    def resolve_text(txt: str, src_section: str | None, visited: set) -> str:
        while True:
            idx = txt.find('${')
            if idx == -1:
                return txt
            start = idx + 2
            end = txt.find('}', start)
            if end == -1:
                return txt
            inner = txt[idx+2:end]

            # lookup raw value
            if src_section is not None and inner in sections.get(src_section, {}):
                raw_val = sections[src_section][inner]
                new_src = src_section
            elif inner in default_section:
                raw_val = default_section[inner]
                new_src = None
            elif ':' in inner:
                sec, sub = inner.split(':', 1)
                if sec == 'DEFAULT':
                    raw_val = default_section.get(sub)
                    if raw_val is None:
                        raise KeyError(f'default key {sub!r} not found')
                    new_src = None
                else:
                    sec_dict = sections.get(sec)
                    if sec_dict is None or sub not in sec_dict:
                        raise KeyError(f'key {sub!r} not found in section {sec!r}')
                    raw_val = sec_dict[sub]
                    new_src = sec
            else:
                raise KeyError(f'key {inner!r} not found')

            if inner in visited:
                raise ValueError('reference cycle')
            visited.add(inner)
            resolved_raw = resolve_text(raw_val, new_src, visited)
            visited.remove(inner)

            txt = txt[:idx] + resolved_raw + txt[end+1:]

    def resolve_value(v: str, src_section: str | None) -> str:
        return resolve_text(v, src_section, set())

    # resolve all section values
    for sec_name, sec_dict in list(sections.items()):
        for k, v in list(sec_dict.items()):
            sec_dict[k] = resolve_value(v, sec_name)

    # resolve default_section values
    for k, v in list(default_section.items()):
        default_section[k] = resolve_value(v, None)

    return sections
